CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <c10/util/Optional.h>

// Tile dimensions for output
#define TILE_W 32
#define TILE_H 8

// Maximum kernel size supported in constant memory
#define MAX_WEIGHT_ELEMS 8192

__constant__ float c_weight[MAX_WEIGHT_ELEMS];

// Border kernel: full bounds checking on input loads
__global__ void __launch_bounds__(TILE_W * TILE_H, 2)
depthwise_conv2d_kernel_border(
    const float* __restrict__ input,
    float* __restrict__ output,
    const float* __restrict__ bias,
    bool has_bias,
    int N, int C,
    int in_h, int in_w,
    int out_h, int out_w,
    int kernel_h, int kernel_w,
    int stride_h, int stride_w,
    int padding_h, int padding_w,
    int dilation_h, int dilation_w
) {
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;

    const int out_col_base = blockIdx.x * TILE_W;
    const int out_row_base = blockIdx.y * TILE_H;
    const int nc = blockIdx.z;
    const int n = nc / C;
    const int c = nc % C;

    extern __shared__ float smem[];

    const int smem_h = (TILE_H - 1) * stride_h + (kernel_h - 1) * dilation_h + 1;
    const int smem_w = (TILE_W - 1) * stride_w + (kernel_w - 1) * dilation_w + 1;

    const int in_row0 = out_row_base * stride_h - padding_h;
    const int in_col0 = out_col_base * stride_w - padding_w;

    const int total_smem = smem_h * smem_w;
    const int num_threads = TILE_H * TILE_W;
    const int tid = ty * TILE_W + tx;
    const float* in_ptr = input + (n * C + c) * in_h * in_w;

    for (int idx = tid; idx < total_smem; idx += num_threads) {
        int sr = idx / smem_w;
        int sc = idx % smem_w;
        int ir = in_row0 + sr;
        int ic = in_col0 + sc;
        float val = 0.0f;
        if (ir >= 0 && ir < in_h && ic >= 0 && ic < in_w) {
            val = in_ptr[ir * in_w + ic];
        }
        smem[idx] = val;
    }

    __syncthreads();

    const int out_row = out_row_base + ty;
    const int out_col = out_col_base + tx;

    if (out_row >= out_h || out_col >= out_w) return;

    const int w_offset = c * kernel_h * kernel_w;

    float acc = 0.0f;
    const int smem_row_start = ty * stride_h;
    const int smem_col_start = tx * stride_w;

    #pragma unroll 1
    for (int kh = 0; kh < kernel_h; kh++) {
        #pragma unroll 1
        for (int kw = 0; kw < kernel_w; kw++) {
            int sr = smem_row_start + kh * dilation_h;
            int sc = smem_col_start + kw * dilation_w;
            acc += smem[sr * smem_w + sc] * c_weight[w_offset + kh * kernel_w + kw];
        }
    }

    if (has_bias) acc += bias[c];

    output[(n * C + c) * out_h * out_w + out_row * out_w + out_col] = acc;
}

// Interior kernel: no bounds checking on input loads (all loads guaranteed valid)
__global__ void __launch_bounds__(TILE_W * TILE_H, 2)
depthwise_conv2d_kernel_interior(
    const float* __restrict__ input,
    float* __restrict__ output,
    const float* __restrict__ bias,
    bool has_bias,
    int N, int C,
    int in_h, int in_w,
    int out_h, int out_w,
    int kernel_h, int kernel_w,
    int stride_h, int stride_w,
    int padding_h, int padding_w,
    int dilation_h, int dilation_w
) {
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;

    const int out_col_base = blockIdx.x * TILE_W;
    const int out_row_base = blockIdx.y * TILE_H;
    const int nc = blockIdx.z;
    const int n = nc / C;
    const int c = nc % C;

    extern __shared__ float smem[];

    const int smem_h = (TILE_H - 1) * stride_h + (kernel_h - 1) * dilation_h + 1;
    const int smem_w = (TILE_W - 1) * stride_w + (kernel_w - 1) * dilation_w + 1;

    const int in_row0 = out_row_base * stride_h - padding_h;
    const int in_col0 = out_col_base * stride_w - padding_w;

    const int total_smem = smem_h * smem_w;
    const int num_threads = TILE_H * TILE_W;
    const int tid = ty * TILE_W + tx;
    const float* in_ptr = input + (n * C + c) * in_h * in_w;

    // Branch-free cooperative load: no bounds check needed
    for (int idx = tid; idx < total_smem; idx += num_threads) {
        int sr = idx / smem_w;
        int sc = idx % smem_w;
        smem[idx] = in_ptr[(in_row0 + sr) * in_w + (in_col0 + sc)];
    }

    __syncthreads();

    const int w_offset = c * kernel_h * kernel_w;

    float acc = 0.0f;
    const int smem_row_start = ty * stride_h;
    const int smem_col_start = tx * stride_w;

    #pragma unroll 1
    for (int kh = 0; kh < kernel_h; kh++) {
        #pragma unroll 1
        for (int kw = 0; kw < kernel_w; kw++) {
            int sr = smem_row_start + kh * dilation_h;
            int sc = smem_col_start + kw * dilation_w;
            acc += smem[sr * smem_w + sc] * c_weight[w_offset + kh * kernel_w + kw];
        }
    }

    if (has_bias) acc += bias[c];

    output[(n * C + c) * out_h * out_w + out_row_base * out_w + out_col_base +
           ty * out_w + tx] = acc;
}

torch::Tensor depthwise_conv2d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias,
    int stride_h, int stride_w,
    int padding_h, int padding_w,
    int dilation_h, int dilation_w
) {
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(input.dtype() == torch::kFloat32, "input must be float32");
    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");
    TORCH_CHECK(weight.is_contiguous(), "weight must be contiguous");
    TORCH_CHECK(weight.size(1) == 1, "weight must have size(1)==1 for depthwise conv");

    const int N = input.size(0);
    const int C = input.size(1);
    const int in_h = input.size(2);
    const int in_w = input.size(3);
    const int kernel_h = weight.size(2);
    const int kernel_w = weight.size(3);

    const int out_h = (in_h + 2 * padding_h - dilation_h * (kernel_h - 1) - 1) / stride_h + 1;
    const int out_w = (in_w + 2 * padding_w - dilation_w * (kernel_w - 1) - 1) / stride_w + 1;

    int num_weight_elems = C * kernel_h * kernel_w;
    TORCH_CHECK(num_weight_elems <= MAX_WEIGHT_ELEMS, "Too many weight elements for constant memory");
    cudaMemcpyToSymbol(c_weight, weight.data_ptr<float>(),
                       num_weight_elems * sizeof(float), 0, cudaMemcpyDeviceToDevice);

    auto output = torch::empty({N, C, out_h, out_w}, input.options());

    const float* bias_ptr = nullptr;
    bool has_bias = false;
    if (bias.has_value() && bias.value().defined()) {
        has_bias = true;
        bias_ptr = bias.value().contiguous().data_ptr<float>();
    }

    dim3 block(TILE_W, TILE_H);

    int smem_h = (TILE_H - 1) * stride_h + (kernel_h - 1) * dilation_h + 1;
    int smem_w = (TILE_W - 1) * stride_w + (kernel_w - 1) * dilation_w + 1;
    int smem_bytes = smem_h * smem_w * sizeof(float);

    // Compute the maximal rectangular region of tiles that are fully interior:
    // For tile (bx, by): input patch starts at (by*TILE_H*stride_h - padding_h, bx*TILE_W*stride_w - padding_w)
    // and extends to (by*TILE_H*stride_h - padding_h + smem_h - 1, bx*TILE_W*stride_w - padding_w + smem_w - 1)
    // Interior condition:
    //   by*TILE_H*stride_h - padding_h >= 0  =>  by >= ceil(padding_h / (TILE_H*stride_h))
    //   bx*TILE_W*stride_w - padding_w >= 0  =>  bx >= ceil(padding_w / (TILE_W*stride_w))
    //   by*TILE_H*stride_h - padding_h + smem_h - 1 < in_h
    //   bx*TILE_W*stride_w - padding_w + smem_w - 1 < in_w

    int total_tiles_x = (out_w + TILE_W - 1) / TILE_W;
    int total_tiles_y = (out_h + TILE_H - 1) / TILE_H;

    // First interior tile indices (inclusive)
    int int_bx_start = (padding_w + TILE_W * stride_w - 1) / (TILE_W * stride_w);
    int int_by_start = (padding_h + TILE_H * stride_h - 1) / (TILE_H * stride_h);
    // Correction: need in_row0 = by*TILE_H*stride_h - padding_h >= 0
    // => by >= ceil(padding_h / (TILE_H*stride_h))
    if (padding_h > 0)
        int_by_start = (padding_h + TILE_H * stride_h - 1) / (TILE_H * stride_h);
    else
