    acc += smem[(smem_row_start + 0) * SMEM_W_3x7 + (smem_col_start + 0)] * c_weight[w_offset + 0];
    acc += smem[(smem_row_start + 0) * SMEM_W_3x7 + (smem_col_start + 1)] * c_weight[w_offset + 1];
