    acc += smem[(smem_row_start + 2) * SMEM_W_3x7 + (smem_col_start + 0)] * c_weight[w_offset + 14];
    acc += smem[(smem_row_start + 2) * SMEM_W_3x7 + (smem_col_start + 1)] * c_weight[w_offset + 15];
    acc += smem[(smem_row_start + 2) * SMEM_W_3x7 + (smem_col_start + 2)] * c_weight[w_offset + 16];
    acc += smem[(smem_row_start + 2) * SMEM_W_3x7 + (smem_col_start + 3)] * c_weight[w_offset + 17];
    acc += smem[(smem_row_start + 2) * SMEM_W_3x7 + (smem_col_start + 4)] * c_weight[w_offset + 18];
    acc += smem[(smem_row_start + 2) * SMEM_W_3x7 + (smem_col_start + 5)] * c_weight[w_offset + 19];
    acc += smem[(smem_row_start + 2) * SMEM_W_3x7 + (smem_col_start + 6)] * c_weight[w_offset + 20];

