}

// Generic kernel for non-specialized cases
__global__ void __launch_bounds__(TILE_W * TILE_H, 4)
depthwise_conv2d_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    const float* __restrict__ bias,
    bool has_bias,
    int N, int C,
    int in_h, int in_w,
    int out_h, int out_w,
    int kernel_h, int kernel_w,
    int stride_h, int stride_w,
    int padding_h, int padding_w,
    int dilation_h, int dilation_w
) {
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;
    const int out_col_base = blockIdx.x * TILE_W;
    const int out_row_base = blockIdx.y * TILE_H;
    const int nc = blockIdx.z;
    const int n = nc / C;
    const int c = nc % C;

    extern __shared__ float smem[];

    const int smem_h = (TILE_H - 1) * stride_h + (kernel_h - 1) * dilation_h + 1;
    const int smem_w = (TILE_W - 1) * stride_w + (kernel_w - 1) * dilation_w + 1;
    const int in_row0 = out_row_base * stride_h - padding_h;
    const int in_col0 = out_col_base * stride_w - padding_w;
    const float* in_ptr = input + (n * C + c) * in_h * in_w;

    for (int sr = ty; sr < smem_h; sr += TILE_H) {
        for (int sc = tx; sc < smem_w; sc += TILE_W) {
            int ir = in_row0 + sr;
            int ic = in_col0 + sc;
            float val = 0.0f;
            if ((unsigned)ir < (unsigned)in_h && (unsigned)ic < (unsigned)in_w) {
                val = __ldg(&in_ptr[ir * in_w + ic]);
            }
            smem[sr * smem_w + sc] = val;
        }
    }

    __syncthreads();

    const int out_row = out_row_base + ty;
    const int out_col = out_col_base + tx;
    if (out_row >= out_h || out_col >= out_w) return;

    const int w_offset = c * kernel_h * kernel_w;
    float acc = 0.0f;
    const int smem_row_start = ty * stride_h;
    const int smem_col_start = tx * stride_w;

    #pragma unroll 1
    for (int kh = 0; kh < kernel_h; kh++) {
        int sr = smem_row_start + kh * dilation_h;
        #pragma unroll 1
        for (int kw = 0; kw < kernel_w; kw++) {
            int sc = smem_col_start + kw * dilation_w;
            acc += smem[sr * smem_w + sc] * c_weight[w_offset + kh * kernel_w + kw];
        }
    }

    if (has_bias) acc += bias[c];
    output[(n * C + c) * out_h * out_w + out_row * out_w + out_col] = acc;
}

torch::Tensor depthwise_conv2d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias,
    int stride_h, int stride_w,
    int padding_h, int padding_w,
    int dilation_h, int dilation_w
) {
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(input.dtype() == torch::kFloat32, "input must be float32");
    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");
    TORCH_CHECK(weight.is_contiguous(), "weight must be contiguous");
    TORCH_CHECK(weight.size(1) == 1, "weight must have size(1)==1 for depthwise conv");

    const int N = input.size(0);
    const int C = input.size(1);
    const int in_h = input.size(2);
    const int in_w = input.size(3);
    const int kernel_h = weight.size(2);
    const int kernel_w = weight.size(3);

    const int out_h = (in_h + 2 * padding_h - dilation_h * (kernel_h - 1) - 1) / stride_h + 1;
    const int out_w = (in_w + 2 * padding_w - dilation_w * (kernel_w - 1) - 1) / stride_w + 1;

    int num_weight_elems = C * kernel_h * kernel_w;
    TORCH_CHECK(num_weight_elems <= MAX_WEIGHT_ELEMS, "Too many weight elements for constant memory");
    cudaMemcpyToSymbol(c_weight, weight.data_ptr<float>(),
                       num_weight_elems * sizeof(float), 0, cudaMemcpyDeviceToDevice);

    auto output = torch::empty({N, C, out_h, out_w}, input.options());

    const float* bias_ptr = nullptr;
    bool has_bias = false;
    if (bias.has_value() && bias.value().defined()) {
        has_bias = true;
        bias_ptr = bias.value().contiguous().data_ptr<float>();
    }

    dim3 block(TILE_W, TILE_H);

    bool use_specialized = (kernel_h == 3 && kernel_w == 7 &&
                            stride_h == 1 && stride_w == 1 &&
                            padding_h == 0 && padding_w == 0 &&
                            dilation_h == 1 && dilation_w == 1);

    if (use_specialized) {
        // For padding=0, stride=1, dilation=1, 3x7 kernel:
        // A tile block at (bx, by) is "interior" if its full smem footprint fits:
        //   rows [out_row_base .. out_row_base + SMEM_H_3x7 - 1] all < in_h
        //   cols [out_col_base .. out_col_base + SMEM_W_3x7 - 1] all < in_w
        // i.e., out_row_base + SMEM_H_3x7 <= in_h  =>  by < interior_grid_h
        //       out_col_base + SMEM_W_3x7 <= in_w  =>  bx < interior_grid_w
        // Note: out_row_base = by * TILE_H, out_col_base = bx * TILE_W
        // Interior condition: by * TILE_H + SMEM_H_3x7 <= in_h
        //                     bx * TILE_W + SMEM_W_3x7 <= in_w

        const int total_grid_x = (out_w + TILE_W - 1) / TILE_W;
        const int total_grid_y = (out_h + TILE_H - 1) / TILE_H;

        // Number of interior tile columns: bx such that bx*TILE_W + SMEM_W_3x7 <= in_w
        // bx <= (in_w - SMEM_W_3x7) / TILE_W
        int interior_grid_x = (in_w - SMEM_W_3x7) / TILE_W + 1;
        if (interior_grid_x < 0) interior_grid_x = 0;
        if (interior_grid_x > total_grid_x) interior_grid_x = total_grid_x;

        // Number of interior tile rows: by such that by*TILE_H + SMEM_H_3x7 <= in_h
        int interior_grid_y = (in_h - SMEM_H_3x7) / TILE_H + 1;
        if (interior_grid_y < 0) interior_grid_y = 0;
        if (interior_grid_y > total_grid_y) interior_grid_y = total_grid_y;

        const int smem_bytes = SMEM_H_3x7 * SMEM_W_3x7 * sizeof(float);

        // Launch interior kernel on the rectangle [0..interior_grid_x) x [0..interior_grid_y)
        if (interior_grid_x > 0 && interior_grid_y > 0) {
            dim3 grid_interior(interior_grid_x, interior_grid_y, N * C);
            depthwise_conv2d_kernel_3x7_interior<<<grid_interior, block, smem_bytes>>>(
                input.data_ptr<float>(),
                output.data_ptr<float>(),
                bias_ptr,
                has_bias,
                N, C,
                in_h, in_w,
                out_h, out_w
            );
        }

        // Launch guarded kernel on all border tiles (right column strip and/or bottom row strip)
        // We handle border tiles as: all tiles NOT in the pure interior rectangle.
        // Strategy: launch guarded kernel for the full grid but skip interior tiles via a guard,
        // OR launch two separate strips. For simplicity and to avoid intra-kernel branching,
        // launch guarded kernel on the full grid and let it redundantly re-do interior tiles
        // only if border strips are non-empty.
        bool has_border_x = (interior_grid_x < total_grid_x);
        bool has_border_y = (interior_grid_y < total_grid_y);

