                    output.data_ptr<float>(),
                    bias_ptr,
                    has_bias,
                    N, C,
                    in_h, in_w,
                    out_h, out_w
                );
                // The above won't work correctly because blockIdx.x maps to wrong tile.
                // Fall back: just launch the full guarded kernel for border.
            }
            // Simpler correct approach: launch guarded kernel for the full grid.
            // The interior kernel already wrote interior outputs; guarded kernel will
            // overwrite them (same values) plus fill border tiles.
            // This wastes some work on interior but is correct and avoids offset complexity.
            dim3 grid_full(total_grid_x, total_grid_y, N * C);
            depthwise_conv2d_kernel_3x7<<<grid_full, block, smem_bytes>>>(
                input.data_ptr<float>(),
                output.data_ptr<float>(),
                bias_ptr,
                has_bias,
                N, C,
                in_h, in_w,
                out_h, out_w
            );
        }
    } else {
